SELECT id, space_id, title, filename, mime, status, source_key, created_by, created_at, published_at, error_message
FROM knowledge_documents
WHERE id = #{id}

SELECT id, space_id, title, filename, mime, status, source_key, created_by, created_at, published_at, error_message
FROM knowledge_documents
WHERE space_id = #{spaceId}
ORDER BY created_at DESC
LIMIT #{limit} OFFSET #{offset}

SELECT id, document_id, kind, status, error_message, created_at, updated_at
FROM knowledge_jobs
WHERE id = #{id}
